#!/usr/bin/env python3\n\"\"\"\uc13c\uc11c \ub370\uc774\ud130 \uc218\uc9d1 \ubc0f \ud559\uc2b5 \ub370\uc774\ud130 \uc0dd\uc131 \uc2a4\ud06c\ub9bd\ud2b8\n\n\uc0ac\uc6a9 \ub2e8\ub1cc:\n    # \ub0c4\uc0c8 \uc885\ub958\ubcc4\ub85c 30\ucd08\uc529 \ub370\uc774\ud130 \uc218\uc9d1\n    python scripts/collect_training_data.py \\\n        --odor_type \"refrigerator\" \\\n        --duration 30 \\\n        --output data/raw/refrigerator.csv\n    \n    # \ubaa8\ub4e0 \ub0c4\uc0c8 \ube0c\uae30 \uc218\uc9d1 (\ub300\ud654\uc2dd)\n    python scripts/collect_training_data.py --interactive\n    \n    # \ub370\uc774\ud130 \uc804\ucc98\ub9ac \ubc0f \ub179\uc77c \ubaa8\ub4e0 \ub370\uc774\ud130 \ud569\uce58\uae30\n    python scripts/collect_training_data.py --process_all\n\"\"\"\n\nimport argparse\nimport time\nimport sys\nfrom pathlib import Path\nfrom datetime import datetime\nimport numpy as np\nimport pandas as pd\nfrom tqdm import tqdm\n\n# \ud504\ub85c\uc81d\ud2b8 \ub8e8\ud2b8\ub85c \uacbd\ub85c \ucd94\uac00\nsys.path.insert(0, str(Path(__file__).parent.parent))\n\nfrom src.sensor_data_collector import SensorDataCollector\nfrom src.data_processor import DataProcessor\nfrom src.feature_extractor import FeatureExtractor\nfrom src.utils import ensure_directory_exists, combine_csv_files\nimport config\n\n\nclass TrainingDataCollector:\n    \"\"\"\\ud559\uc2b5 \ub370\uc774\ud130 \uc218\uc9d1 \ub4dc\ub77c\uc774\ubc84\"\"\"\n    \n    def __init__(self, config_dict: dict = None):\n        \"\"\"\n        \ucd08\uae30\ud654\n        \n        Args:\n            config_dict: \uc124\uc815 \ub529\uc154\ub108\ub9ac (\uae30\ubcf8: config.py\uc758 SENSOR_CONFIG)\n        \"\"\"\n        self.sensor_config = config_dict or config.SENSOR_CONFIG\n        self.preprocessing_config = config.PREPROCESSING_CONFIG\n        self.feature_config = config.FEATURE_CONFIG\n        \n        # \uace7 \ub530\ub978 \ub370\uc774\ud130\ub85c \uc2dc\ub098\ub9ac\uc624\ub97c \ub300\ube44\ud558\uae30 \uc704\ud55c \uce90\ub97c\n        self.USE_SIMULATION = True  # \uc2e4\uc81c \uc13c\uc11c\ub85c \ubaa0\ub2f4\uc5a4\uc5f0 \uc2dc \False\ub85c \ubcc0\uacbd\n        \n        self.sensor_collector = SensorDataCollector(self.sensor_config)\n        self.data_processor = DataProcessor(self.preprocessing_config)\n        self.feature_extractor = FeatureExtractor(self.feature_config)\n        \n        # \ub370\uc774\ud130 \ub514\ub809\ud1a0\ub9ac \uc0dd\uc131\n        ensure_directory_exists(config.RAW_DATA_DIR)\n        ensure_directory_exists(config.PROCESSED_DATA_DIR)\n        ensure_directory_exists(config.DATA_DIR / 'training_data')\n    \n    def simulate_sensor_data(self, odor_type: str, duration: int, \n                            sampling_rate: int = 10) -> pd.DataFrame:\n        \"\"\"\n        \ub0c4\uc0c8 \uc885\ub958\ubcc4\ub85c \uc13c\uc11c \ub370\uc774\ud130 \uc2b5\ub1d0\ub808\uc774\uc158\n        \n        \ub0c4\uc0c8 \uc885\ub958\ubcc4 \ub2e8\uc704 \uc2e0\ud638 \uc2a4\ud0c0\uc77c:\n        - refrigerator: \uba85\ub0a4\uace7\uc774\uace7 \ubcc0\ud558\ub294 \uc2e0\ud638\n        - industrial: \ub192\uc740 \uc911\ub0a4/\uac10\ub3c4\n        - decay: \ub290\ub9b0\ub371\ub098\uc5f0 \uadf8\ub791 \uc911\ub0a4\n        - chemical: \uc548\uc815\ub41c \ub192\uc740 \uc911\ub0a4\n        - smoke: \ub293\ub824\ub2ec\ub2f4\n        \n        Args:\n            odor_type: \ub0c4\uc0c8 \uc885\ub958\n            duration: \uc218\uc9d1 \uc2dc\uac04 (\ucd08)\n            sampling_rate: \uc0d8\ud50c\ub9c1 \ub808\uc774\ud2b8 (Hz)\n        \n        Returns:\n            \uc2dc\ubbac\ub808\uc774\uc158\ub41c \ub370\uc774\ud130 DataFrame\n        \"\"\"\n        data_list = []\n        num_samples = duration * sampling_rate\n        interval = 1.0 / sampling_rate\n        start_time = time.time()\n        \n        # \ub0c4\uc0c8 \uc885\ub958\ubcc4 \uae30\ubcf8 \uac12\n        odor_profiles = {\n            'normal': {\n                'gas_mean': 350,\n                'gas_std': 20,\n                'gas_trend': 'flat',\n                'temp_mean': 25,\n                'humidity_mean': 50,\n            },\n            'refrigerator': {\n                'gas_mean': 500,\n                'gas_std': 80,\n                'gas_trend': 'oscillate',  # \uba85\ub0a4\uace7\uc774 \uc601\ud5a5 \ubc1b\ub294 \ub0c4\uc0c8\n                'temp_mean': 15,\n                'humidity_mean': 60,\n            },\n            'industrial': {\n                'gas_mean': 1200,\n                'gas_std': 150,\n                'gas_trend': 'increasing',  # \uc911\ub0a4 \uae09\uc99d\n                'temp_mean': 30,\n                'humidity_mean': 40,\n            },\n            'decay': {\n                'gas_mean': 800,\n                'gas_std': 120,\n                'gas_trend': 'smooth_increase',  # \uc11c\uc11c \uc911\ub0a4 \uac10\ub3c4 \uc6c3\n                'temp_mean': 28,\n                'humidity_mean': 70,\n            },\n            'chemical': {\n                'gas_mean': 1500,\n                'gas_std': 200,\n                'gas_trend': 'spike',  # \uae09\uaca9\ud55c \uc2a4\ud30c\uc774\ud06c\n                'temp_mean': 25,\n                'humidity_mean': 30,\n            },\n            'smoke': {\n                'gas_mean': 1000,\n                'gas_std': 100,\n                'gas_trend': 'rapid_increase',  # \ube60\ub978 \uc911\ub0a4 \uac10\ub3c4\n                'temp_mean': 35,\n                'humidity_mean': 20,\n            },\n        }\n        \n        profile = odor_profiles.get(odor_type.lower(), odor_profiles['normal'])\n        \n        # \ub370\uc774\ud130 \uc0dd\uc131\n        for i in tqdm(range(num_samples), desc=f\"{odor_type} \ub370\uc774\ud130 \uc2dd\ub280\ub808\uc774\uc158\", unit=\"sample\"):\n            # \uac00\uc2a4 \uc13c\uc11c \ub370\uc774\ud130 \uc0dd\uc131\n            if profile['gas_trend'] == 'flat':\n                gas_value = np.random.normal(profile['gas_mean'], profile['gas_std'])\n            elif profile['gas_trend'] == 'oscillate':\n                # \uba85\ub0a4\uace7 \ubcc0\ud558\ub294 \ud328\ud134\n                gas_value = profile['gas_mean'] + profile['gas_std'] * np.sin(2 * np.pi * i / 50) + np.random.normal(0, 10)\n            elif profile['gas_trend'] == 'increasing':\n                # \ub192\uc544\uc9c0\ub294 \uc911\ub0a4\n                trend = i / num_samples * 300\n                gas_value = profile['gas_mean'] + trend + np.random.normal(0, profile['gas_std'])\n            elif profile['gas_trend'] == 'smooth_increase':\n                # \uc11c\uc11c \ub192\uc544\uc9c0\ub294 \uc911\ub0a4\n                trend = (i / num_samples) ** 1.5 * 200\n                gas_value = profile['gas_mean'] + trend + np.random.normal(0, profile['gas_std'])\n            elif profile['gas_trend'] == 'spike':\n                # \uc2a4\ud30c\uc774\ud06c \uae30\ubc18 \ub0c4\uc0c8\n                if 0.4 < (i / num_samples) < 0.6:\n                    gas_value = profile['gas_mean'] + 500 + np.random.normal(0, profile['gas_std'])\n                else:\n                    gas_value = np.random.normal(profile['gas_mean'], profile['gas_std'])\n            elif profile['gas_trend'] == 'rapid_increase':\n                # \ube60\ub978 \uc911\ub0a4 \uac10\ub3c4\n                trend = i / num_samples * 400\n                gas_value = profile['gas_mean'] + trend + np.random.normal(0, profile['gas_std'])\n            else:\n                gas_value = np.random.normal(profile['gas_mean'], profile['gas_std'])\n            \n            # \ubcf4\uc815 \ubc94\uc704\ub85c \uc870\uc815 (0 \uc774\uc0c1)\n            gas_value = max(0, gas_value)\n            \n            # \uc628\ub3c4/\uc2b5\ub3c4\ub294 \ub290\ub9bd\ub2e4\uac8c \ubcc0\ud568\n            temperature = profile['temp_mean'] + np.random.normal(0, 1)\n            humidity = profile['humidity_mean'] + np.random.normal(0, 3)\n            \n            data_list.append({\n                'gas': gas_value,\n                'temperature': temperature,\n                'humidity': humidity,\n                'timestamp': start_time + i * interval,\n                'odor_label': odor_type.lower(),\n            })\n        \n        return pd.DataFrame(data_list)\n    \n    def collect_raw_data(self, odor_type: str, duration: int, \n                        output_path: Path = None, sampling_rate: int = 10) -> Path:\n        \"\"\"\n        \uc6d0\ubcf8 \uc13c\uc11c \ub370\uc774\ud130 \uc218\uc9d1\n        \n        Args:\n            odor_type: \ub0c4\uc0c8 \uc885\ub958\n            duration: \uc218\uc9d1 \uc2dc\uac04 (\ucd08)\n            output_path: \uc800\uc7a5 \uacbd\ub85c (\uae30\ubcf8: data/raw/{odor_type}.csv)\n            sampling_rate: \uc0d8\ud50c\ub9c1 \ub808\uc774\ud2b8\n        \n        Returns:\n            \uc800\uc7a5\ub41c \ud30c\uc77c \uacbd\ub85c\n        \"\"\"\n        print(f\"\\n[{'='*60}]\")\n        print(f\"\ub0c4\uc0c8 \uc885\ub958: {odor_type}\")\n        print(f\"\uc218\uc9d1 \uc2dc\uac04: {duration}\ucd08\")\n        print(f\"[{'='*60}]\\n\")\n        \n        if output_path is None:\n            output_path = config.RAW_DATA_DIR / f\"{odor_type}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.csv\"\n        else:\n            output_path = Path(output_path)\n        \n        # \ub370\uc774\ud130 \uc218\uc9d1\n        if self.USE_SIMULATION:\n            print(f\"\ud83d\udcc4 \uc2e4\uc81c \uc13c\uc11c \ub370\uc774\ud130 \ub300\uc2e0 \uc2b5\ub1d0\ub808\uc774\uc158 \ub370\uc774\ud130 \uc0dd\uc131 \uc911...\\n\")\n            raw_data = self.simulate_sensor_data(odor_type, duration, sampling_rate)\n        else:\n            print(f\"\ud83d\udcc4 \uc2e4\uc81c \uc13c\uc11c\ub85c\ubd80\ud130 \ub370\uc774\ud130 \uc218\uc9d1 \uc911...\\n\")\n            raw_data = self.sensor_collector.collect_data(duration, sampling_rate)\n            raw_data['odor_label'] = odor_type.lower()\n        \n        # \ub370\uc774\ud130 \uc800\uc7a5\n        ensure_directory_exists(output_path.parent)\n        raw_data.to_csv(output_path, index=False)\n        print(f\"\\u2713 \ub370\uc774\ud130 \uc800\uc7a5 \uc644\ub8cc: {output_path}\")\n        print(f\"  - \uc0d8\ud50c \uc218: {len(raw_data)}\\n\")\n        \n        return output_path\n    \n    def process_raw_data(self, input_path: Path, output_path: Path = None) -> Path:\n        \"\"\"\n        \uc6d0\ubcf8 \ub370\uc774\ud130 \uc804\ucc98\ub9ac\n        \n        Args:\n            input_path: \uc6d0\ubcf8 \ub370\uc774\ud130 \uacbd\ub85c\n            output_path: \uc804\ucc98\ub9ac\ub41c \ub370\uc774\ud130 \uc800\uc7a5 \uacbd\ub85c\n        \n        Returns:\n            \uc800\uc7a5\ub41c \ud30c\uc77c \uacbd\ub85c\n        \"\"\"\n        print(f\"\\n[\ub370\uc774\ud130 \uc804\ucc98\ub9ac \uc911...] {input_path.name}\")\n        \n        if output_path is None:\n            output_path = config.PROCESSED_DATA_DIR / input_path.name.replace('.csv', '_processed.csv')\n        else:\n            output_path = Path(output_path)\n        \n        # \ub370\uc774\ud130 \ub85c\ub4dc\n        raw_data = pd.read_csv(input_path)\n        \n        # \uc804\ucc98\ub9ac\n        processed_data = self.data_processor.preprocess_dataframe(raw_data)\n        \n        # \ub370\uc774\ud130 \uc800\uc7a5\n        ensure_directory_exists(output_path.parent)\n        processed_data.to_csv(output_path, index=False)\n        print(f\"\\u2713 \uc804\ucc98\ub9ac \ub41c \ub370\uc774\ud130 \uc800\uc7a5: {output_path}\\n\")\n        \n        return output_path\n    \n    def extract_features(self, input_path: Path, output_path: Path = None, \n                        window_size: int = 50) -> Path:\n        \"\"\"\n        \ub370\uc774\ud130\uc5d0\uc11c \ud2b9\uc9d5 \ucd94\ucd9c\n        \n        Args:\n            input_path: \uc804\ucc98\ub9ac\ub41c \ub370\uc774\ud130 \uacbd\ub85c\n            output_path: \ud2b9\uc9d5 \uc800\uc7a5 \uacbd\ub85c\n            window_size: \uc708\ub3c4\uc6b0 \ud06c\uae30\n        \n        Returns:\n            \uc800\uc7a5\ub41c \ud30c\uc77c \uacbd\ub85c\n        \"\"\"\n        print(f\"\\n[\ud2b9\uc9d5 \ucd94\ucd9c \uc911...] {input_path.name}\")\n        \n        if output_path is None:\n            output_path = config.PROCESSED_DATA_DIR / input_path.name.replace('_processed.csv', '_features.csv')\n        else:\n            output_path = Path(output_path)\n        \n        # \ub370\uc774\ud130 \ub85c\ub4dc\n        processed_data = pd.read_csv(input_path)\n        \n        # \ud2b9\uc9d5 \ucd94\ucd9c\n        features = self.feature_extractor.extract_features_from_dataframe(\n            processed_data, \n            window_size=window_size\n        )\n        \n        # \ub370\uc774\ud130 \uc800\uc7a5\n        ensure_directory_exists(output_path.parent)\n        features.to_csv(output_path, index=False)\n        print(f\"\\u2713 \ud2b9\uc9d5 \uc800\uc7a5: {output_path}\")\n        print(f\"  - \ub179 \uc218: {len(features)}\")\n        print(f\"  - \uc911\ub798\ub2dd \ub0c4\uc0c8: {features['odor_label'].unique().tolist()}\\n\")\n        \n        return output_path\n    \n    def interactive_collection(self):\n        \"\"\"\ub300\ud654\uc2dd \ub0c4\uc0c8 \ub370\uc774\ud130 \uc218\uc9d1\"\"\"\n        print(\"\\n\" + \"=\"*70)\n        print(\"\ud83d\udcc4 \ub300\ud654\uc2dd \ud559\uc2b5 \ub370\uc774\ud130 \uc218\uc9d1 \ubaa8\ub4dc\")\n        print(\"=\"*70)\n        \n        odor_types = list(config.ODOR_LABELS.values())\n        collected_files = []\n        \n        for idx, odor_name in enumerate(odor_types, 1):\n            print(f\"\\n[{idx}/{len(odor_types)}] {odor_name} \ub0c4\uc0c8 \ub370\uc774\ud130\")\n            \n            # \uc0ac\uc6a9\uc790\uac00 \uc9c8\ub97c \ub300\ub85c \ube48\uce5c\ub4a4\ub97c \udo60\uba38\ub108\ub9ac\uac00 \uacf5\uae30\ub97c \ub300\uccb4 \ub3d9\uc548 \ub370\uc774\ud130 \uc218\uc9d1\n            duration = int(input(f\"  \u22a3 \uc218\uc9d1 \uc2dc\uac04 (\ucd08) [\uae30\ubcf8: 30]: \") or \"30\")\n            \n            # \ub370\uc774\ud130 \uc218\uc9d1\n            raw_path = self.collect_raw_data(\n                odor_type=odor_name.lower(),\n                duration=duration,\n            )\n            collected_files.append(raw_path)\n            \n            input(f\"  \u22a3 \ub2e4\uc74c \ub0c4\uc0c8\ub97c \uc900\ube44\ud55c \uba38 Enter \ud0a4\ub97c \ub204\ub978 \ud6c4 \ub4b3\uac14\uc2a4 \ub204\ub978\ud55c \ud6c4 \ub4b3\uac14\uc2a4 \ub204\ub978\ud55c\")\n        \n        return collected_files\n    \n    def process_all_data(self, raw_dir: Path = None):\n        \"\"\"\n        \ub514\ub809\ud1a0\ub9ac\uc758 \ubaa8\ub4e0 \ub0c4\uc0c8 \ub370\uc774\ud130 \uc804\ucc98\ub9ac \ubc0f \ud2b9\uc9d5 \ucd94\ucd9c\n        \n        Args:\n            raw_dir: \uc6d0\ubcf8 \ub370\uc774\ud130 \ub514\ub809\ud1a0\ub9ac\n        \"\"\"\n        raw_dir = raw_dir or config.RAW_DATA_DIR\n        \n        print(f\"\\n[\ub514\ub809\ud1a0\ub9ac \uc815\ub8e8: {raw_dir}]\\n\")\n        \n        raw_files = list(raw_dir.glob('*.csv'))\n        \n        if not raw_files:\n            print(f\"\ud83d\ude14 CSV \ud30c\uc77c\uc744 \ucc3e\uc744 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4: {raw_dir}\")\n            return\n        \n        print(f\"\ucd1d {len(raw_files)}\uac1c\uc758 \ub0c4\uc0c8 \ub370\uc774\ud130 \ucc98\ub9ac\\n\")\n        \n        all_features = []\n        \n        for raw_file in raw_files:\n            try:\n                # 1. \ub370\uc774\ud130 \uc804\ucc98\ub9ac\n                processed_path = self.process_raw_data(raw_file)\n                \n                # 2. \ud2b9\uc9d5 \ucd94\ucd9c\n                features_path = self.extract_features(processed_path)\n                \n                # 3. \ub2b9\ub2f5\ub41c \ub370\uc774\ud130 \uac01\ub2f5\n                features_df = pd.read_csv(features_path)\n                all_features.append(features_df)\n                \n            except Exception as e:\n                print(f\"\\u26a0\ufe0f  \uc625\ub958 [{raw_file.name}]: {e}\\n\")\n                continue\n        \n        # 4. \ubaa8\ub4e0 \ub185\ub2f9\ub41c \ub370\uc774\ud130 \ud569\uce58\uae30\n        if all_features:\n            combined_features = pd.concat(all_features, ignore_index=True)\n            \n            # \uc640\ub2f5\uc3a8\ub41d \ub370\uc774\ud130 \uc800\uc7a5\n            training_path = config.TRAINING_DATA_PATH\n            ensure_directory_exists(training_path.parent)\n            combined_features.to_csv(training_path, index=False)\n            \n            print(f\"\\n{'-'*70}\")\n            print(f\"\\u2705 \ud559\uc2b5 \ub370\uc774\ud130 \uc800\uc7a5 \uc644\ub8cc!\")\n            print(f\"{'-'*70}\")\n            print(f\"\\ud30c\uc77c \uacbd\ub85c: {training_path}\")\n            print(f\"\ucd1d \ub179 \uc218: {len(combined_features)}\")\n            print(f\"\ub0c4\uc0c8 \uc885\ub958: {combined_features['odor_label'].unique().tolist()}\")\n            print(f\"\ub0c4\uc0c8\ubcc4 \ub179 \uc218:\")\n            print(combined_features['odor_label'].value_counts().to_string())\n            print(f\"{'-'*70}\\n\")\n\n\ndef main():\n    parser = argparse.ArgumentParser(\n        description=\"\ub0c4\uc0c8 \uac10\uc9c0 \uc2dc\uc2a4\ud15c\uc744 \uc704\ud55c \ud559\uc2b5 \ub370\uc774\ud130 \uc218\uc9d1\",\n        formatter_class=argparse.RawDescriptionHelpFormatter,\n        epilog=\"\"\"\n\uc0ac\uc6a9 \uc608\uc2dc:\n  # \uae30\ubcf8 \ub370\uc774\ud130 \uc218\uc9d1 (\ub0c4\uc0c8 \uc885\ub958\ubcc4 30\ucd08\uc529)\n  python scripts/collect_training_data.py --basic\n  \n  # \ub0c9\uc7a5\uace0 \ub0c4\uc0c8 \ub0c8\ub2f4 \ub370\uc774\ud130 30\ucd08 \uc218\uc9d1\n  python scripts/collect_training_data.py --odor_type refrigerator --duration 30\n  \n  # \ub300\ud654\uc2dd \ubaa8\ub4dc (\ub0c4\uc0c8\ubcc4\ub85c \uc9c8\ub054\uce64 \ub0b3\uae30\uace0 \uc785\ub825)\n  python scripts/collect_training_data.py --interactive\n  \n  # \ubaa8\ub4e0 \ub0c4\uc0c8 \ub370\uc774\ud130\ub97c \uc804\ucc98\ub9ac \ubc0f \ud2b9\uc9d5 \ucd94\ucd9c\n  python scripts/collect_training_data.py --process_all\n        \"\"\"\n    )\n    \n    parser.add_argument(\n        '--basic',\n        action='store_true',\n        help='\uae30\ubcf8 \ubaa8\ub4dc: \ubaa8\ub4e0 \ub0c4\uc0c8 \uc885\ub958\ubcc4 30\ucd08\uc529 \ub370\uc774\ud130 \uc218\uc9d1 \ubc0f \uc804\ucc98\ub9ac'\n    )\n    \n    parser.add_argument(\n        '--odor_type',\n        type=str,\n        help=f'\ub0c4\uc0c8 \uc885\ub958 ({[\", \".join(config.ODOR_LABELS.values())]})'\n    )\n    \n    parser.add_argument(\n        '--duration',\n        type=int,\n        default=30,\n        help='\ub370\uc774\ud130 \uc218\uc9d1 \uc2dc\uac04 (\ucd08) [\uae30\ubcf8: 30]'\n    )\n    \n    parser.add_argument(\n        '--output',\n        type=str,\n        help='\uc800\uc7a5 \uacbd\ub85c'\n    )\n    \n    parser.add_argument(\n        '--interactive',\n        action='store_true',\n        help='\ub300\ud654\uc2dd \ubaa8\ub4dc: \uac01 \ub0c4\uc0c8\ubcc4\ub85c \uc0ac\uc6a9\uc790 \uc9c8\ub054\uce64\ub97c \uc5bb\uc544\ub9d0\uacfc\ub3d9 \ub370\uc774\ud130 \uc218\uc9d1'\n    )\n    \n    parser.add_argument(\n        '--process_all',\n        action='store_true',\n        help='\ubaa8\ub4e0 \ub0c4\uc0c8 \ub370\uc774\ud130 \uc804\ucc98\ub9ac \ubc0f \ud2b9\uc9d5 \ucd94\ucd9c'\n    )\n    \n    parser.add_argument(\n        '--window_size',\n        type=int,\n        default=50,\n        help='\uc708\ub3c4\uc6b0 \ud06c\uae30 [\uae30\ubcf8: 50]'\n    )\n    \n    args = parser.parse_args()\n    \n    # \ub370\uc774\ud130 \uc218\uc9d1\uae30 \ucd08\uae30\ud654\n    collector = TrainingDataCollector()\n    \n    try:\n        if args.basic:\n            # \uae30\ubcf8 \ubaa8\ub4dc: \ubaa8\ub4e0 \ub0c4\uc0c8 \uc885\ub958 \ub370\uc774\ud130 \uc218\uc9d1\n            print(\"\\n\" + \"=\"*70)\n            print(\"\ud83d\udcc4 \uae30\ubcf8 \ubaa8\ub4dc: \ubaa8\ub4e0 \ub0c4\uc0c8 \uc885\ub958 \ub370\uc774\ud130 \uc218\uc9d1 \uc2dc\uc791\")\n            print(\"=\"*70)\n            \n            collected_files = []\n            for odor_type in config.ODOR_LABELS.values():\n                raw_path = collector.collect_raw_data(\n                    odor_type=odor_type.lower(),\n                    duration=args.duration,\n                )\n                collected_files.append(raw_path)\n            \n            # \ubaa8\ub4e0 \ub370\uc774\ud130 \uc804\ucc98\ub9ac \ubc0f \ud2b9\uc9d5 \ucd94\ucd9c\n            collector.process_all_data()\n        \n        elif args.interactive:\n            # \ub300\ud654\uc2dd \ubaa8\ub4dc\n            collector.interactive_collection()\n            collector.process_all_data()\n        \n        elif args.process_all:\n            # \ubaa8\ub4e0 \ub0c4\uc0c8 \ub370\uc774\ud130 \uc804\ucc98\ub9ac\n            collector.process_all_data()\n        \n        elif args.odor_type:\n            # \ud2b9\uc815 \ub0c4\uc0c8 \ub370\uc774\ud130 \uc218\uc9d1\n            raw_path = collector.collect_raw_data(\n                odor_type=args.odor_type,\n                duration=args.duration,\n                output_path=args.output,\n            )\n            \n            # \ub370\uc774\ud130 \uc804\ucc98\ub9ac\n            processed_path = collector.process_raw_data(raw_path)\n            \n            # \ud2b9\uc9d5 \ucd94\ucd9c\n            features_path = collector.extract_features(\n                processed_path,\n                window_size=args.window_size,\n            )\n        \n        else:\n            parser.print_help()\n    \n    except KeyboardInterrupt:\n        print(\"\\n\\n\u26a0\ufe0f  \uc0ac\uc6a9\uc790\uac00 \uc911\ub2e8\ud588\uc2b5\ub2c8\ub2e4.\")\n    except Exception as e:\n        print(f\"\\n\\u274c \uc611\ub7ec \ubc1c\uc0dd: {e}\")\n        import traceback\n        traceback.print_exc()\n    finally:\n        # \uc13c\uc11c \uc5f0\uacb0 \uc885\ub8cc\n        collector.sensor_collector.close()\n\n\nif __name__ == '__main__':\n    main()\n